import{_ as t,o as g,c as o,a3 as a}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Bảng công cuối kỳ (tự gửi)","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/nop-bang-cong.md","filePath":"huong-dan/nop-bang-cong.md","lastUpdated":1783009205000}'),c={name:"huong-dan/nop-bang-cong.md"};function i(h,n,r,e,s,u){return g(),o("div",null,[...n[0]||(n[0]=[a('<h1 id="bang-cong-cuoi-ky-tu-gui" tabindex="-1">Bảng công cuối kỳ (tự gửi) <a class="header-anchor" href="#bang-cong-cuoi-ky-tu-gui" aria-label="Permalink to &quot;Bảng công cuối kỳ (tự gửi)&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Rà soát bảng công trước khi hệ thống tự gửi về Bộ Phận Chấm Công. <strong>👤 Ai làm được:</strong> Mọi nhân sự. · <strong>⏱️ Khoảng:</strong> ~1 phút.</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Không cần nộp thủ công</p><p>Bảng công <strong>tự chốt &amp; gửi</strong> khi tới thời gian cấu hình của công ty — bạn không phải bấm &quot;Nộp&quot;. Việc của bạn là <strong>chấm công đầy đủ</strong> và khai bù công / tăng ca cho ngày thiếu <strong>trước</strong> thời điểm đó.</p></div><h2 id="cac-buoc" tabindex="-1">Các bước <a class="header-anchor" href="#cac-buoc" aria-label="Permalink to &quot;Các bước&quot;">​</a></h2><ol><li>Vào <strong>Dữ Liệu Chấm Công</strong> → <strong>Tra Cứu Dữ Liệu Công</strong>.</li><li>Dùng mũi tên chọn đúng <strong>tháng</strong>; kiểm tra ngày công, tổng giờ ở các tab <strong>Tổng Hợp / App / Vân Tay</strong>.</li><li>Thiếu hoặc sai ngày nào → khai <strong>Bù công</strong> / <strong>Tăng ca</strong> ngay trên ngày đó (xem <a href="/help/huong-dan/bu-cong-tang-ca.html">hướng dẫn</a>).</li><li>Xong — không cần thao tác gì thêm. Tới hạn, hệ thống tự gửi bảng công của kỳ.</li></ol><h2 id="✅-ket-qua" tabindex="-1">✅ Kết quả <a class="header-anchor" href="#✅-ket-qua" aria-label="Permalink to &quot;✅ Kết quả&quot;">​</a></h2><p>Khi tới <strong>thời gian tự gửi</strong>, bảng công của kỳ được chốt và gửi về Bộ Phận Chấm Công. Quản lý có thể theo dõi ở phân hệ <strong>Bảng Công</strong> (chỉ xem).</p><h2 id="💡-meo-luu-y" tabindex="-1">💡 Mẹo &amp; lưu ý <a class="header-anchor" href="#💡-meo-luu-y" aria-label="Permalink to &quot;💡 Mẹo &amp; lưu ý&quot;">​</a></h2><ul><li>Rà soát <strong>trước</strong> thời điểm tự gửi — sau khi gửi, số liệu đã chốt.</li><li>Không chắc mốc tự gửi của công ty? Hỏi quản lý hoặc Phòng HCNS (cấu hình trong <em>Quy Tắc Chấm Công</em>).</li><li>Tải chi tiết tháng: bấm <strong>CSV</strong>.</li></ul><p><em>Chi tiết: <a href="/help/chuc-nang/cham-cong.html#_2-tra-cuu-du-lieu-cong">Tra cứu dữ liệu công</a></em></p>',10)])])}const p=t(c,[["render",i]]);export{m as __pageData,p as default};
